-- blank なしの 12keys MusicXML をフレーズディフェンスへ登録
-- C F Bb Eb Ab Db Gb B E A D G / 3回完成で次 / BPM 160 / 難易度7 / 生存120秒
BEGIN;

  id, slug, stage_number, title, title_en, bpm, beats_per_bar, phrase_bars,
  audio_registration_mode, audio_url, staff_layout, attack_trigger, key_fifths,
  required_completion_count, difficulty_level, survive_seconds, player_hp,
  production_staff_hint_mode, production_keyboard_hint_mode, play_style, is_active, sort_order
) VALUES (
  uuid_generate_v5('a0000000-0000-4000-8000-000000000001'::uuid, 'defense-dev-essential-licks-1'), 'defense-dev-essential-licks-1', 925, 'essential licks 1', 'Essential Licks 1',
  160, 4, 2, 'single_source', 'https://jazzify-cdn.com/sozai/essential-licks-12keys/essential-licks-1.mp3?v=202611121700', 'treble', 'note', 0,
  3, 7, 120, 20, 'always', 'always', 'phrase', true, 925
)
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  title_en = EXCLUDED.title_en,
  bpm = EXCLUDED.bpm,
  phrase_bars = EXCLUDED.phrase_bars,
  audio_url = EXCLUDED.audio_url,
  required_completion_count = EXCLUDED.required_completion_count,
  difficulty_level = EXCLUDED.difficulty_level,
  survive_seconds = EXCLUDED.survive_seconds;

DELETE FROM public.defense_phrases WHERE stage_id = (SELECT id FROM public.defense_stages WHERE slug = 'defense-dev-essential-licks-1');
DELETE FROM public.defense_stage_progression_chords WHERE stage_id = (SELECT id FROM public.defense_stages WHERE slug = 'defense-dev-essential-licks-1');

  id, course_id, title, title_en, description, description_en,
  premium_only, order_index, block_number, block_name, block_name_en, nav_links
) VALUES (
  uuid_generate_v5('a0000000-0000-4000-8000-000000000001'::uuid, 'developer-essential-licks-1-lesson'), uuid_generate_v5('a0000000-0000-4000-8000-000000000001'::uuid, 'course-developer-test'), 'essential licks 1', 'Essential Licks 1',
  'フレーズディフェンス。12キー（C F Bb Eb Ab Db Gb B E A D G）、3回正解で次のフレーズ。BPM 160、難易度7、生存2分。',
  'Phrase Defense across 12 keys. 3 completions advance. BPM 160, difficulty 7, survive 2 minutes.',
  false,
  (SELECT COALESCE(MAX(order_index), 0) + 1 FROM public.lessons WHERE course_id = uuid_generate_v5('a0000000-0000-4000-8000-000000000001'::uuid, 'course-developer-test')),
  1, 'テスト', 'Test', '["lesson"]'::jsonb
)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  description_en = EXCLUDED.description_en;
  id, lesson_id, song_id, order_index, is_clear_required, clear_conditions,
  is_fantasy, is_survival, is_ear_training, is_balloon_rush,
  is_survival_tutorial, is_ear_training_tutorial, is_video_lesson, is_defense,
  defense_stage_id, title, title_en
) VALUES (
  uuid_generate_v5('a0000000-0000-4000-8000-000000000001'::uuid, 'developer-essential-licks-1-lsong-0'), uuid_generate_v5('a0000000-0000-4000-8000-000000000001'::uuid, 'developer-essential-licks-1-lesson'), NULL, 0, true, '{"count": 1, "rank": "S"}'::jsonb,
  false, false, false, false, false, false, false, true, (SELECT id FROM public.defense_stages WHERE slug = 'defense-dev-essential-licks-1'), 'essential licks 1', 'Essential Licks 1'
)
ON CONFLICT (id) DO UPDATE SET
  defense_stage_id = EXCLUDED.defense_stage_id,
  title = EXCLUDED.title;


UPDATE public.defense_stages SET
  bpm = 160,
  beats_per_bar = 4,
  phrase_bars = 2,
  audio_registration_mode = 'single_source',
  audio_url = 'https://jazzify-cdn.com/sozai/essential-licks-12keys/essential-licks-2-1.mp3?v=202611121700',
  required_completion_count = 3,
  difficulty_level = 7,
  survive_seconds = 120,
  play_style = 'phrase'
WHERE slug = 'defense-dev-essential-licks-2-1';

