  description_en = 'Phrase Defense across 12 keys. 3 completions advance. BPM 160, difficulty 7, survive 2 minutes.'
WHERE id = (
  SELECT l.id FROM public.lessons l
  JOIN public.lesson_songs ls ON ls.lesson_id = l.id
  JOIN public.defense_stages s ON s.id = ls.defense_stage_id
  WHERE s.slug = 'defense-dev-essential-licks-2-1'
  LIMIT 1
